-- ============================================================
-- SECTION 2: Helper — safe side creation (idempotent)
-- ============================================================
local function addSideSafe(name)
    local ok, result = pcall(ScenEdit_AddSide, {name = name})
    if not ok then
        print("[WARN] addSide(" .. name .. "): " .. tostring(result))
    end
end

local function setPostureSafe(sideA, sideB, posture)
    local ok, err = pcall(ScenEdit_SetSidePosture, sideA, sideB, posture)
    if not ok then
        print("[WARN] setPosture(" .. sideA .. "," .. sideB .. "," .. posture .. "): " .. tostring(err))
    end
end

