print("[PHASE 8] Creating special actions for manual control...")

local function addManualStrike(saId, desc, attackerName, targetName, wpnDbId)
    local script = string.format([[
local attacker = ScenEdit_GetUnit({name='%s'})
local target   = ScenEdit_GetUnit({name='%s'})
if not attacker then
    print('[ERROR] Attacker %s not found')
    return
end
if not target then
    print('[ERROR] Target %s not found')
    return
end
print('[STRIKE] ' .. attacker.name .. ' launching weapon (dbid=%d) at ' .. target.name)
local ok, err = pcall(ScenEdit_AttackContact, attacker.guid, target.guid, {weapon_dbid=%d})
if not ok then
    print('[ERROR] ' .. tostring(err))
end
]], attackerName, targetName, attackerName, targetName, wpnDbId, wpnDbId)

    ScenEdit_AddSpecialAction({
        Side = SIDE.RED,
        ActionNameOrID = saId,
        description = desc,
        IsActive   = true,
        IsRepeatable = true,
        ScriptText = script,
    })
    print("  + Special action: " .. desc)
end

-- DDG1 → 蓝方伯克舰1 (YJ-18 shipborne)
