    "local t3 = ScenEdit_GetUnit({name='蓝方补给舰'})" .. LfCR ..
    LfCR ..
    "local function fire(unitName, target, wpnDbId)" .. LfCR ..
    "  if not target then return end" .. LfCR ..
    "  local u = ScenEdit_GetUnit({name=unitName})" .. LfCR ..
    "  if u then" .. LfCR ..
    "    pcall(ScenEdit_AttackContact, u.guid, target.guid, {weapon_dbid=wpnDbId})" .. LfCR ..
    "  end" .. LfCR ..
    "end" .. LfCR ..
    LfCR ..
    "-- Saturation fire from multiple axes" .. LfCR ..
    "-- Axis 1: J16-1 → Burke 1 (YJ-12)" .. LfCR ..
    "fire('J16-1', t1, 2862)" .. LfCR ..
    "-- Axis 2: J16-2 → Burke 2 (YJ-12)" .. LfCR ..
    "fire('J16-2', t2, 2862)" .. LfCR ..
    "-- Axis 3: J16-3 + J16-4 → Supply (YJ-12)" .. LfCR ..
    "fire('J16-3', t3, 2862)" .. LfCR ..
    "fire('J16-4', t3, 2862)" .. LfCR ..
    "-- Axis 4: 055-DD-1 → Burke 1, 2, AO (YJ-18 dbid=2867)" .. LfCR ..
    "fire('055-DD-1 [Nanchang]', t1, 2867)" .. LfCR ..
    "fire('055-DD-1 [Nanchang]', t2, 2867)" .. LfCR ..
    "fire('055-DD-1 [Nanchang]', t3, 2867)" .. LfCR ..
    "-- Axis 5: 055-DD-2 → all targets (YJ-18)" .. LfCR ..
    "fire('055-DD-2', t1, 2867)" .. LfCR ..
    "fire('055-DD-2', t2, 2867)" .. LfCR ..
    "fire('055-DD-2', t3, 2867)" .. LfCR ..
    "-- Axis 6: 039C-SUB-1 → Supply (YJ-83 dbid=541)" .. LfCR ..
    "fire('039C-SUB-1', t3, 541)" .. LfCR ..
    LfCR ..
    "ScenEdit_SpecialMessage(SIDE.RED, '[阶段3] 多轴饱和攻击 — 反舰导弹齐射！')"
})
ScenEdit_SetEventAction("Ev_Phase3_SaturationAttack", {mode = "add", name = "Act_Phase3"})
