    "  end" .. LfCR ..
    "end" .. LfCR ..
    "local msg = string.format('[阶段4] BDA: %d/3 targets destroyed', destroyed)" .. LfCR ..
    "ScenEdit_SpecialMessage(SIDE.RED, msg)" .. LfCR ..
    "if destroyed >= 2 then" .. LfCR ..
    "  ScenEdit_SetScore(SIDE.RED, 500, 'Mission Success: Blue force attritted')" .. LfCR ..
    "  ScenEdit_SpecialMessage(SIDE.RED, '【作战成功】摧毁' .. destroyed .. '个目标')" .. LfCR ..
    "elseif destroyed > 0 then" .. LfCR ..
    "  ScenEdit_SpecialMessage(SIDE.RED, '【部分达成】摧毁' .. destroyed .. '个目标，继续监控')" .. LfCR ..
    "else" .. LfCR ..
    "  ScenEdit_SpecialMessage(SIDE.RED, '【未达成】目标仍存活，考虑补充打击')" .. LfCR ..
    "end"
})
ScenEdit_SetEventAction("Ev_Phase4_BDA", {mode = "add", name = "Act_Phase4"})
